@import url('https://fonts.googleapis.com/css2?family=Black+Ops+One&family=Inter:wght@400;500;600;700&family=JetBrains+Mono:wght@400;500;600;700&display=swap');

/* CrossFit DNA — forged dark steel, red intensity, stencil grit, affiliate blue */
.theme-crossfit-dna {
  --bg: oklch(0.218 0 0);
  --surface: oklch(0.260 0 0);
  --surface-2: oklch(0.301 0 0);
  --fg: oklch(1.000 0 0);
  --fg-muted: oklch(0.648 0.007 286.2);
  --accent: oklch(0.520 0.201 28.0);
  --accent-fg: oklch(1.000 0 0);
  --accent-2: oklch(0.499 0.179 257.9);
  --line: oklch(1 0 0 / 14%);
  --success: oklch(0.615 0.143 147.4);
  --warning: oklch(0.788 0.151 74.9);
  --danger: oklch(0.55 0.2 27);
  --radius: 2px;
  --radius-sm: 1px;
  --radius-lg: 3px;
  --radius-pill: 3px;
  --shadow-1: 0 2px 6px oklch(0 0 0 / 45%);
  --shadow-2: 0 8px 24px oklch(0 0 0 / 55%);
  --shadow-3: 0 24px 56px oklch(0 0 0 / 65%);
  --glow: 0 0 0 1px color-mix(in oklab, var(--accent) 45%, transparent);
  --border-width: 1px;
  --blur-amount: 0px;
  --font-display: "Black Ops One", sans-serif;
  --font-body: "Inter", sans-serif;
  --font-mono: "JetBrains Mono", ui-monospace, monospace;
  --tracking-display: 0.03em;
  --label-transform: uppercase;
  --label-tracking: 0.16em;

  background-color: var(--bg);
  color: var(--fg);
  font-family: var(--font-body);
}

.theme-crossfit-dna h1,
.theme-crossfit-dna h2,
.theme-crossfit-dna h3 {
  font-family: var(--font-display);
  letter-spacing: var(--tracking-display);
}

/* signature */
.theme-crossfit-dna { background-image: repeating-linear-gradient(45deg, oklch(1 0 0 / 2%) 0 2px, transparent 2px 8px); }
.theme-crossfit-dna h1, .theme-crossfit-dna h2 { text-transform: uppercase; }
.theme-crossfit-dna button { text-transform: uppercase; letter-spacing: 0.1em; font-weight: 700; }
.theme-crossfit-dna button:active { transform: scale(0.97); }

/* depth */
.theme-crossfit-dna ::selection { background: var(--accent); color: var(--accent-fg); }
.theme-crossfit-dna thead th { font-family: var(--font-display); text-transform: uppercase; letter-spacing: 0.12em; font-weight: 400; font-size: 0.8em; background: var(--surface-2); border-bottom: 2px solid var(--accent); }
.theme-crossfit-dna td { border-bottom: 1px solid var(--line); font-variant-numeric: tabular-nums; }
.theme-crossfit-dna tbody tr:hover { background: color-mix(in oklab, var(--accent) 12%, transparent); }
.theme-crossfit-dna a { color: var(--fg); font-weight: 700; text-decoration: underline; text-decoration-color: var(--accent); text-decoration-thickness: 2px; text-underline-offset: 3px; }
.theme-crossfit-dna a:hover { color: var(--accent-fg); background: var(--accent); text-decoration: none; }
.theme-crossfit-dna input, .theme-crossfit-dna select, .theme-crossfit-dna textarea { background: oklch(0.18 0 0); border: 1px solid oklch(1 0 0 / 25%); border-radius: var(--radius-sm); color: var(--fg); }
.theme-crossfit-dna input:focus-visible, .theme-crossfit-dna select:focus-visible, .theme-crossfit-dna textarea:focus-visible { outline: none; border-color: var(--accent); box-shadow: inset 0 0 0 1px var(--accent), 0 0 12px color-mix(in oklab, var(--accent) 40%, transparent); }
.theme-crossfit-dna kbd { border: 3px solid oklch(1 0 0 / 45%); border-radius: 9999px; padding: 0.1em 0.55em; background: oklch(0.18 0 0); font-weight: 700; }
.theme-crossfit-dna .label-caps { font-family: var(--font-display); font-weight: 400; color: var(--fg-muted); }
.theme-crossfit-dna .themed-border { border-left: 4px solid var(--accent); border-top: 1px solid oklch(1 0 0 / 20%); }
.theme-crossfit-dna button { box-shadow: inset 0 -3px 0 oklch(0 0 0 / 40%); }
.theme-crossfit-dna button:active { transform: scale(0.97) translateY(1px); box-shadow: inset 0 2px 4px oklch(0 0 0 / 50%); }
.theme-crossfit-dna ::-webkit-scrollbar { width: 12px; height: 12px; }
.theme-crossfit-dna ::-webkit-scrollbar-track { background: oklch(0.18 0 0); }
.theme-crossfit-dna ::-webkit-scrollbar-thumb { background: oklch(0.40 0 0); border: 2px solid oklch(0.18 0 0); border-radius: 2px; }
.theme-crossfit-dna ::-webkit-scrollbar-thumb:hover { background: var(--accent); }

/* alt mode: the whiteboard — WOD scores in marker on gym whiteboard */
.theme-crossfit-dna.alt-mode {
  --bg: oklch(0.98 0.000 0.0);
  --surface: oklch(0.955 0.000 0.0);
  --surface-2: oklch(0.92 0.000 0.0);
  --fg: oklch(0.17 0.005 270);
  --fg-muted: oklch(0.46 0.01 270);
  --line: oklch(0.87 0.005 270);
  --accent: oklch(0.500 0.201 28.0);
  --danger: oklch(0.500 0.201 28.0);
  --shadow-1: 0 1px 2px oklch(0 0 0 / 8%);
  --shadow-2: 0 6px 20px -8px oklch(0 0 0 / 15%);
  --shadow-3: 0 20px 50px -16px oklch(0 0 0 / 20%);
  background-image: repeating-linear-gradient(180deg, transparent 0 38px, oklch(0.17 0.005 270 / 5%) 38px 39px);
}
.theme-crossfit-dna.alt-mode input, .theme-crossfit-dna.alt-mode select, .theme-crossfit-dna.alt-mode textarea { background: oklch(1 0 0); border-color: oklch(0 0 0 / 30%); color: var(--fg); }
.theme-crossfit-dna.alt-mode kbd { border-color: oklch(0 0 0 / 40%); background: oklch(1 0 0); }
.theme-crossfit-dna.alt-mode a:hover { color: oklch(1 0 0); }
.theme-crossfit-dna.alt-mode thead th { background: var(--surface-2); }
.theme-crossfit-dna.alt-mode ::-webkit-scrollbar-track { background: var(--surface); }
.theme-crossfit-dna.alt-mode ::-webkit-scrollbar-thumb { background: oklch(0.70 0 0); border-color: var(--surface); }
.theme-crossfit-dna.alt-mode .themed-border { border-top-color: oklch(0 0 0 / 15%); }

/* Bridge shadcn semantic variables to the theme tokens so stock shadcn/ui
   components are skinned by the theme. Scope-safe: applies inside the theme
   class only. */
[class*="theme-"] {
  --background: var(--bg);
  --foreground: var(--fg);
  --card: var(--surface);
  --card-foreground: var(--fg);
  --popover: var(--surface);
  --popover-foreground: var(--fg);
  --primary: var(--accent);
  --primary-foreground: var(--accent-fg);
  --secondary: var(--surface-2);
  --secondary-foreground: var(--fg);
  --muted: var(--surface-2);
  --muted-foreground: var(--fg-muted);
  --accent-foreground: var(--accent-fg);
  --border: var(--line);
  --input: var(--line);
  --ring: var(--accent);
  --destructive: var(--danger);
  --destructive-foreground: var(--accent-fg);

  /* Full app surface: sidebar, charts, app-level font + shadow + tracking vars.
     These are what real products (shadcn full kit, RootCX-style UI kits) consume —
     without them a retrofit looks half-themed. */
  --sidebar: var(--surface-2);
  --sidebar-foreground: var(--fg);
  --sidebar-primary: var(--accent);
  --sidebar-primary-foreground: var(--accent-fg);
  --sidebar-accent: color-mix(in oklab, var(--accent) 12%, var(--surface-2));
  --sidebar-accent-foreground: var(--fg);
  --sidebar-border: var(--line);
  --sidebar-ring: var(--accent);

  --chart-1: var(--accent);
  --chart-2: var(--accent-2);
  --chart-3: var(--success);
  --chart-4: var(--warning);
  --chart-5: var(--danger);

  --font-sans: var(--font-body);
  --font-heading: var(--font-app, var(--font-display));
  --font-serif: var(--font-display);

  --shadow-2xs: var(--shadow-1);
  --shadow-xs: var(--shadow-1);
  --shadow-sm: var(--shadow-1);
  --shadow: var(--shadow-2);
  --shadow-md: var(--shadow-2);
  --shadow-lg: var(--shadow-3);
  --shadow-xl: var(--shadow-3);
  --shadow-2xl: var(--shadow-3);

  --tracking-normal: 0em;
}

/* Base experience: make the theme own the canvas and native elements even in
   apps that never adopted semantic classes. Scoped to the theme wrapper. */
[class*="theme-"] {
  background-color: var(--bg);
  color: var(--fg);
  font-family: var(--font-body);
}
[class*="theme-"] :is(h1, h2, h3, h4) { font-family: var(--font-display); }
[class*="theme-"] :is(code, pre, kbd, samp) { font-family: var(--font-mono); }
[class*="theme-"] ::selection { background: color-mix(in oklab, var(--accent) 30%, transparent); }

/* OPT-IN HARD MODE — add "sf-enforce" beside the theme class when the host app
   bakes font/shadow/radius literals into its compiled utilities (a var bridge
   cannot beat a literal). Targeted !important, fonts and surfaces only. */
[class*="theme-"].sf-enforce { font-family: var(--font-body) !important; }
[class*="theme-"].sf-enforce :is(h1, h2, h3, h4, [class*="font-heading"]) {
  font-family: var(--font-app, var(--font-display)) !important;
  letter-spacing: var(--tracking-display) !important;
}
/* Data stays data: metrics/KPIs keep the body face with aligned lining figures.
   The display face is for headlines ONLY — never on numbers. Opt specific
   elements INTO the display face with data-sf="display". */
[class*="theme-"] :is([class*="text-2xl"], [class*="text-3xl"], [class*="text-4xl"], [class*="text-5xl"]) {
  font-variant-numeric: lining-nums tabular-nums;
}
[class*="theme-"].sf-enforce [data-sf="display"] {
  font-family: var(--font-display) !important;
  letter-spacing: var(--tracking-display) !important;
}
[class*="theme-"] :is(.sf-num, [data-sf="num"]) {
  font-family: var(--font-body) !important;
  font-variant-numeric: lining-nums tabular-nums;
}
[class*="theme-"].sf-enforce :is(button, [role="button"]) { font-family: var(--font-ui, var(--font-body)) !important; }
[class*="theme-"].sf-enforce :is(code, pre, kbd) { font-family: var(--font-mono) !important; }
[class*="theme-"].sf-enforce :is(.bg-card, [class*="card"]) {
  box-shadow: var(--shadow-2) !important;
  border-radius: var(--radius-lg) !important;
  border: var(--border-width) solid var(--line) !important;
}
[class*="theme-"].sf-enforce :is([class*="shadow-sm"], [class*="shadow-md"]) { box-shadow: var(--shadow-1) !important; }
[class*="theme-"].sf-enforce :is([class*="shadow-lg"], [class*="shadow-xl"]) { box-shadow: var(--shadow-3) !important; }
